51	const std::string AUTH_DEFAULT_USER("anonymous");
52	const std::string AUTH_DEFAULT_PASSWD("ARIA2USER@");
53	} // namespace
54	
55	AuthConfigFactory::AuthConfigFactory() {}
56	
57	AuthConfigFactory::~AuthConfigFactory() = default;
58	
59	std::unique_ptr<AuthConfig>
60	AuthConfigFactory::createAuthConfig(const std::shared_ptr<Request>& request,
61	                                    const Option* op)
62	{
63	  if (request->getProtocol() == "http" || request->getProtocol() == "https") {
64	    if (op->getAsBool(PREF_HTTP_AUTH_CHALLENGE)) {
65	      if (!request->getUsername().empty()) {
66	        updateBasicCred(make_unique<BasicCred>(
67	            request->getUsername(), request->getPassword(), request->getHost(),
68	            request->getPort(), request->getDir(), true));
69	        return AuthConfig::create(request->getUsername(),
70	                                  request->getPassword());
71	      }
72	      auto i = findBasicCred(request->getHost(), request->getPort(),
73	                             request->getDir());
74	      if (i == std::end(basicCreds_)) {
75	        return nullptr;
76	      }
77	      else {
78	        return AuthConfig::create((*i)->user_, (*i)->password_);
79	      }
80	    }
81	    else {
82	      if (!request->getUsername().empty()) {
83	        return AuthConfig::create(request->getUsername(),
84	                                  request->getPassword());
85	      }
86	      else {
87	        return createHttpAuthResolver(op)->resolveAuthConfig(
88	            request->getHost());
89	      }
90	    }
91	  }
92	  else if (request->getProtocol() == "ftp" ||
93	           request->getProtocol() == "sftp") {
94	    if (!request->getUsername().empty()) {
95	      if (request->hasPassword()) {
96	        return AuthConfig::create(request->getUsername(),
97	                                  request->getPassword());
98	      }
99	      else {
100	        if (!op->getAsBool(PREF_NO_NETRC)) {
101	          // First, check we have password corresponding to host and
102	          // username
103	          NetrcAuthResolver authResolver;
104	          authResolver.setNetrc(netrc_.get());
105	
106	          auto ac = authResolver.resolveAuthConfig(request->getHost());
107	          if (ac && ac->getUser() == request->getUsername()) {
108	            return ac;
109	          }
110	        }
111	        // We don't have password for host and username. Return
112	        // password specified by --ftp-passwd
113	        return AuthConfig::create(request->getUsername(),
114	                                  op->get(PREF_FTP_PASSWD));
115	      }
116	    }
117	    else {
118	      return createFtpAuthResolver(op)->resolveAuthConfig(request->getHost());
119	    }
120	  }
121	  else {
122	    return nullptr;
123	  }
124	}
125	
126	std::unique_ptr<AuthResolver>
127	AuthConfigFactory::createHttpAuthResolver(const Option* op) const
128	{
129	  std::unique_ptr<AbstractAuthResolver> resolver;
130	  if (op->getAsBool(PREF_NO_NETRC)) {
131	    resolver = make_unique<DefaultAuthResolver>();
132	  }
133	  else {
134	    auto authResolver = make_unique<NetrcAuthResolver>();
135	    authResolver->setNetrc(netrc_.get());
136	    authResolver->ignoreDefault();
137	    resolver = std::move(authResolver);
138	  }
139	  resolver->setUserDefinedCred(op->get(PREF_HTTP_USER),
140	                               op->get(PREF_HTTP_PASSWD));
141	  return std::move(resolver);
142	}
