144	std::unique_ptr<AuthResolver>
145	AuthConfigFactory::createFtpAuthResolver(const Option* op) const
146	{
147	  std::unique_ptr<AbstractAuthResolver> resolver;
148	  if (op->getAsBool(PREF_NO_NETRC)) {
149	    resolver = make_unique<DefaultAuthResolver>();
150	  }
151	  else {
152	    auto authResolver = make_unique<NetrcAuthResolver>();
153	    authResolver->setNetrc(netrc_.get());
154	    resolver = std::move(authResolver);
155	  }
156	  resolver->setUserDefinedCred(op->get(PREF_FTP_USER),
157	                               op->get(PREF_FTP_PASSWD));
158	  resolver->setDefaultCred(AUTH_DEFAULT_USER, AUTH_DEFAULT_PASSWD);
159	  return std::move(resolver);
160	}
