162	void AuthConfigFactory::setNetrc(std::unique_ptr<Netrc> netrc)
163	{
164	  netrc_ = std::move(netrc);
165	}
166	
167	void AuthConfigFactory::updateBasicCred(std::unique_ptr<BasicCred> basicCred)
168	{
169	  auto i = basicCreds_.lower_bound(basicCred);
170	  if (i != std::end(basicCreds_) && *i == basicCred) {
171	    *(*i) = std::move(*basicCred);
172	  }
173	  else {
174	    basicCreds_.insert(i, std::move(basicCred));
175	  }
176	}
177	
178	bool AuthConfigFactory::activateBasicCred(const std::string& host,
179	                                          uint16_t port,
180	                                          const std::string& path,
181	                                          const Option* op)
182	{
183	  auto i = findBasicCred(host, port, path);
184	  if (i == std::end(basicCreds_)) {
185	    auto authConfig = createHttpAuthResolver(op)->resolveAuthConfig(host);
186	    if (!authConfig) {
187	      return false;
188	    }
189	    else {
190	      basicCreds_.insert(make_unique<BasicCred>(authConfig->getUser(),
191	                                                authConfig->getPassword(), host,
192	                                                port, path, true));
193	      return true;
194	    }
195	  }
196	  else {
197	    (*i)->activate();
198	    return true;
199	  }
200	}
201	
202	BasicCred::BasicCred(std::string user, std::string password, std::string host,
203	                     uint16_t port, std::string path, bool activated)
204	    : user_(std::move(user)),
205	      password_(std::move(password)),
206	      host_(std::move(host)),
207	      port_(port),
208	      path_(std::move(path)),
209	      activated_(activated)
210	{
211	  if (path_.empty() || path_[path_.size() - 1] != '/') {
212	    path_ += "/";
213	  }
214	}
215	
216	void BasicCred::activate() { activated_ = true; }
217	
218	bool BasicCred::isActivated() const { return activated_; }
219	
220	bool BasicCred::operator==(const BasicCred& cred) const
221	{
222	  return host_ == cred.host_ && port_ == cred.port_ && path_ == cred.path_;
223	}
224	
225	bool BasicCred::operator<(const BasicCred& cred) const
226	{
227	  return host_ < cred.host_ || (!(cred.host_ < host_) &&
228	                                (port_ < cred.port_ || (!(cred.port_ < port_) &&
229	                                                        path_ > cred.path_)));
230	}
231	
232	AuthConfigFactory::BasicCredSet::iterator
233	AuthConfigFactory::findBasicCred(const std::string& host, uint16_t port,
234	                                 const std::string& path)
235	{
236	  auto bc = make_unique<BasicCred>("", "", host, port, path);
237	  auto i = basicCreds_.lower_bound(bc);
238	  for (;
239	       i != std::end(basicCreds_) && (*i)->host_ == host && (*i)->port_ == port;
240	       ++i) {
241	    if (util::startsWith(bc->path_, (*i)->path_)) {
242	      return i;
243	    }
244	  }
245	  return std::end(basicCreds_);
246	}
