112	void skipMacdef(BufferedFile& fp)
113	{
114	  std::string s;
115	  while (1) {
116	    s = fp.getLine();
117	    if (s.empty() || fp.eof()) {
118	      break;
119	    }
120	    if (!fp) {
121	      throw DL_ABORT_EX("Netrc:I/O error.");
122	    }
123	    if (s[0] == '\n' || s[0] == '\r') {
124	      break;
125	    }
126	  }
127	}
