129	
130	void Netrc::parse(const std::string& path)
131	{
132	  authenticators_.clear();
133	  BufferedFile fp(path.c_str(), BufferedFile::READ);
134	  if (!fp) {
135	    throw DL_ABORT_EX(fmt("Cannot open file: %s", path.c_str()));
136	  }
137	  enum STATE {
138	    GET_TOKEN,
139	    SET_MACHINE,
140	    SET_LOGIN,
141	    SET_PASSWORD,
142	    SET_ACCOUNT,
143	    SET_MACDEF
144	  };
145	  std::unique_ptr<Authenticator> authenticator;
146	  STATE state = GET_TOKEN;
147	  while (1) {
148	    std::string line = fp.getLine();
149	    if (line.empty()) {
150	      if (fp.eof()) {
151	        break;
152	      }
153	      else if (!fp) {
154	        throw DL_ABORT_EX("Netrc:I/O error.");
155	      }
156	      else {
157	        continue;
158	      }
159	    }
160	    if (line[0] == '#') {
161	      continue;
