82	bool Cookie::match(const std::string& requestHost,
83	                   const std::string& requestPath, time_t date,
84	                   bool secure) const
85	{
86	  if ((secure_ && !secure) || isExpired(date) ||
87	      !cookie::pathMatch(requestPath, path_)) {
88	    return false;
89	  }
90	  if (hostOnly_) {
91	    return requestHost == domain_;
92	  }
93	  else {
94	    return cookie::domainMatch(requestHost, domain_);
95	  }
96	}
