114	std::string Cookie::toNsCookieFormat() const
115	{
116	  std::stringstream ss;
117	  if (!hostOnly_) {
118	    ss << ".";
119	  }
120	  ss << domain_ << "\t";
121	  if (hostOnly_) {
122	    ss << "FALSE";
123	  }
124	  else {
125	    ss << "TRUE";
126	  }
127	  ss << "\t";
128	  ss << path_ << "\t";
129	  if (secure_) {
130	    ss << "TRUE";
131	  }
132	  else {
133	    ss << "FALSE";
134	  }
135	  ss << "\t";
136	  if (persistent_) {
137	    ss << expiryTime_;
138	  }
139	  else {
140	    ss << 0;
141	  }
142	  ss << "\t";
143	  ss << name_ << "\t";
144	  ss << value_;
145	  return ss.str();
146	}
