311	                                  const std::string& requestHost,
312	                                  const std::string& defaultPath, time_t now)
313	{
314	  auto cookie = cookie::parse(setCookieString, requestHost, defaultPath, now);
315	  return cookie && store(std::move(cookie), now);
316	}
