378	DomainNode* findNode(const std::string& domain, DomainNode* node)
379	{
380	  auto labels = splitDomainLabel(domain);
381	  for (auto i = labels.rbegin(), eoi = labels.rend(); i != eoi && node; ++i) {
382	    node = node->findNext(*i);
383	  }
384	  return node;
385	}
386	} // namespace
