52	{
53	  return c == 0x09u || in(c, 0x20u, 0x2fu) || in(c, 0x3bu, 0x40u) ||
54	         in(c, 0x5bu, 0x60u) || in(c, 0x7bu, 0x7eu);
55	}
56	} // namespace
