83	bool parseDate(time_t& time, std::string::const_iterator first,
84	               std::string::const_iterator last)
85	{
86	  // Following algorithm is described in
87	  // http://tools.ietf.org/html/rfc6265#section-5.1.1
88	  std::vector<std::string> dateTokens;
89	  for (std::string::const_iterator i = first, eoi = last; i != eoi;) {
90	    unsigned char c = *i;
91	    if (isDelimiter(c)) {
92	      ++i;
93	      continue;
94	    }
95	    std::string::const_iterator s = i;
96	    for (; s != eoi && !isDelimiter(static_cast<unsigned char>(*s)); ++s)
97	      ;
98	    dateTokens.push_back(std::string(i, s));
99	    i = s;
100	  }
101	  int dayOfMonth = 0;
102	  bool foundDayOfMonth = false;
103	  int month = 0;
104	  bool foundMonth = false;
105	  int year = 0;
106	  bool foundYear = false;
107	  int hour = 0;
108	  int minute = 0;
109	  int second = 0;
110	  bool foundTime = false;
111	  for (std::vector<std::string>::const_iterator i = dateTokens.begin(),
112	                                                eoi = dateTokens.end();
113	       i != eoi; ++i) {
114	    if (!foundTime) {
115	      std::string::const_iterator hEnd;
116	      std::string::const_iterator mEnd;
117	      std::string::const_iterator sEnd;
118	      hEnd = getNextDigit((*i).begin(), (*i).end());
119	      size_t len = std::distance((*i).begin(), hEnd);
120	      if (len == 0 || 2 < len || hEnd == (*i).end() || *hEnd != ':') {
121	        goto NOT_TIME;
122	      }
123	      mEnd = getNextDigit(hEnd + 1, (*i).end());
124	      len = std::distance(hEnd + 1, mEnd);
125	      if (len == 0 || 2 < len || mEnd == (*i).end() || *mEnd != ':') {
126	        goto NOT_TIME;
127	      }
128	      sEnd = getNextDigit(mEnd + 1, (*i).end());
129	      len = std::distance(mEnd + 1, sEnd);
130	      if (len == 0 || 2 < len) {
131	        goto NOT_TIME;
132	      }
133	      foundTime = true;
134	      hour = getInteger((*i).begin(), hEnd);
135	      minute = getInteger(hEnd + 1, mEnd);
136	      second = getInteger(mEnd + 1, sEnd);
137	      continue;
138	    NOT_TIME:;
139	    }
140	    if (!foundDayOfMonth) {
141	      std::string::const_iterator j = getNextDigit((*i).begin(), (*i).end());
142	      size_t len = std::distance((*i).begin(), j);
143	      if (1 <= len && len <= 2) {
144	        foundDayOfMonth = true;
145	        dayOfMonth = getInteger((*i).begin(), j);
146	        continue;
147	      }
148	    }
149	    if (!foundMonth) {
150	      static const char MONTH[][12] = {"jan", "feb", "mar", "apr",
151	                                       "may", "jun", "jul", "aug",
152	                                       "sep", "oct", "nov", "dec"};
153	      if ((*i).size() >= 3) {
154	        bool found = false;
155	        size_t j;
156	        for (j = 0; j < 12; ++j) {
157	          if (util::strieq((*i).begin(), (*i).begin() + 3, &MONTH[j][0],
158	                           &MONTH[j][3])) {
159	            found = true;
160	            break;
161	          }
162	        }
163	        if (found) {
164	          foundMonth = true;
165	          month = j + 1;
166	          continue;
167	        }
168	      }
169	    }
170	    if (!foundYear) {
171	      std::string::const_iterator j = getNextDigit((*i).begin(), (*i).end());
172	      size_t len = std::distance((*i).begin(), j);
173	      if (1 <= len && len <= 4) {
174	        foundYear = true;
175	        year = getInteger((*i).begin(), j);
176	        continue;
177	      }
178	    }
179	  }
180	  if (in(year, 70, 99)) {
181	    year += 1900;
182	  }
183	  else if (in(year, 0, 69)) {
184	    year += 2000;
185	  }
186	  if (!foundDayOfMonth || !foundMonth || !foundYear || !foundTime ||
187	      !in(dayOfMonth, 1, 31) || year < 1601 || hour > 23 || minute > 59 ||
188	      second > 59) {
189	    return false;
190	  }
191	  if ((month == 4 || month == 6 || month == 9 || month == 11) &&
192	      dayOfMonth > 30) {
193	    return false;
194	  }
195	  if (month == 2) {
196	    if ((year % 4 == 0 && year % 100 != 0) || year % 400 == 0) {
197	      if (dayOfMonth > 29) {
198	        return false;
199	      }
200	    }
201	    else if (dayOfMonth > 28) {
202	      return false;
203	    }
204	  }
205	
206	  tm timespec;
207	  memset(&timespec, 0, sizeof(timespec));
208	  timespec.tm_sec = second;
209	  timespec.tm_min = minute;
210	  timespec.tm_hour = hour;
211	  timespec.tm_mday = dayOfMonth;
212	  timespec.tm_mon = month - 1;
213	  timespec.tm_year = year - 1900;
214	  time = timegm(&timespec);
215	
216	  return time != -1;
217	}
218	
219	std::unique_ptr<Cookie> parse(const std::string& cookieStr,
220	                              const std::string& requestHost,
221	                              const std::string& defaultPath,
222	                              time_t creationTime)
223	{
224	  // This implementation is based on the algorithm listed in
225	  // http://tools.ietf.org/html/rfc6265
226	  std::string::const_iterator nvEnd = cookieStr.begin();
227	  std::string::const_iterator end = cookieStr.end();
228	  for (; nvEnd != end && *nvEnd != ';'; ++nvEnd)
229	    ;
230	  std::string::const_iterator eq = cookieStr.begin();
231	  for (; eq != nvEnd && *eq != '='; ++eq)
232	    ;
233	  if (eq == nvEnd) {
234	    return nullptr;
235	  }
236	  std::pair<std::string::const_iterator, std::string::const_iterator> p =
237	      util::stripIter(cookieStr.begin(), eq);
238	  if (p.first == p.second) {
239	    return nullptr;
240	  }
241	  Scip cookieName(p.first, p.second);
242	  p = util::stripIter(eq + 1, nvEnd);
243	  p = util::stripIter(p.first, p.second, "\"");
244	  Scip cookieValue(p.first, p.second);
245	  time_t expiryTime = 0;
246	  bool foundExpires = false;
247	  bool persistent = false;
248	  time_t maxAge = 0;
249	  bool foundMaxAge = false;
250	  std::string cookieDomain;
251	  bool hostOnly = false;
252	  std::string cookiePath;
253	  bool secure = false;
254	  bool httpOnly = false;
255	
256	  if (nvEnd != end) {
257	    ++nvEnd;
258	  }
259	  for (std::string::const_iterator i = nvEnd; i != end;) {
260	    std::string::const_iterator j = std::find(i, end, ';');
261	    std::string::const_iterator eq = std::find(i, j, '=');
262	    p = util::stripIter(i, eq);
263	    std::pair<std::string::const_iterator, std::string::const_iterator> attrp;
264	    if (eq == j) {
265	      attrp.first = attrp.second = j;
266	    }
267	    else {
268	      attrp = util::stripIter(eq + 1, j);
269	    }
270	    i = j;
271	    if (j != end) {
272	      ++i;
273	    }
274	    if (util::strieq(p.first, p.second, "expires")) {
275	      if (parseDate(expiryTime, attrp.first, attrp.second)) {
276	        foundExpires = true;
277	      }
278	      else {
279	        return nullptr;
280	      }
281	    }
282	    else if (util::strieq(p.first, p.second, "max-age")) {
283	      if (attrp.first == attrp.second ||
284	          (!in(static_cast<unsigned char>(*attrp.first), 0x30u, 0x39u) &&
285	           *attrp.first != '-')) {
286	        return nullptr;
287	      }
288	      for (std::string::const_iterator s = attrp.first + 1, eos = attrp.second;
289	           s != eos; ++s) {
290	        if (!in(static_cast<unsigned char>(*s), 0x30u, 0x39u)) {
291	          return nullptr;
292	        }
293	      }
294	      int64_t delta;
295	      if (util::parseLLIntNoThrow(delta,
296	                                  std::string(attrp.first, attrp.second))) {
297	        foundMaxAge = true;
298	        if (delta <= 0) {
299	          maxAge = 0;
300	        }
301	        else {
302	          int64_t n = creationTime;
303	
304	          if (n > std::numeric_limits<int64_t>::max() - delta) {
305	            maxAge = std::numeric_limits<time_t>::max();
306	          }
307	          else {
308	            n += delta;
309	
310	            if (n < 0 || std::numeric_limits<time_t>::max() < n) {
311	              maxAge = std::numeric_limits<time_t>::max();
312	            }
313	            else {
314	              maxAge = n;
315	            }
316	          }
317	        }
318	      }
319	      else {
320	        return nullptr;
321	      }
322	    }
323	    else if (util::strieq(p.first, p.second, "domain")) {
324	      if (attrp.first == attrp.second) {
325	        return nullptr;
326	      }
327	      std::string::const_iterator noDot = attrp.first;
328	      std::string::const_iterator end = attrp.second;
329	      for (; noDot != end && *noDot == '.'; ++noDot)
330	        ;
331	      if (noDot == end) {
332	        return nullptr;
333	      }
334	      cookieDomain.assign(noDot, end);
335	    }
336	    else if (util::strieq(p.first, p.second, "path")) {
337	      if (goodPath(attrp.first, attrp.second)) {
338	        cookiePath.assign(attrp.first, attrp.second);
339	      }
340	      else {
341	        cookiePath = defaultPath;
342	      }
343	    }
344	    else if (util::strieq(p.first, p.second, "secure")) {
345	      secure = true;
346	    }
347	    else if (util::strieq(p.first, p.second, "httponly")) {
348	      httpOnly = true;
349	    }
350	  }
351	
352	  if (foundMaxAge) {
353	    expiryTime = maxAge;
354	    persistent = true;
355	  }
356	  else if (foundExpires) {
357	    persistent = true;
358	  }
359	  else {
360	    expiryTime = std::numeric_limits<time_t>::max();
361	    persistent = false;
362	  }
363	
364	  std::string canonicalizedHost = canonicalizeHost(requestHost);
365	  if (cookieDomain.empty()) {
366	    hostOnly = true;
367	    cookieDomain = canonicalizedHost;
368	  }
369	  else if (domainMatch(canonicalizedHost, cookieDomain)) {
370	    hostOnly = util::isNumericHost(canonicalizedHost);
371	  }
372	  else {
373	    return nullptr;
374	  }
375	
376	  if (cookiePath.empty()) {
377	    cookiePath = defaultPath;
378	  }
379	
380	  auto cookie = make_unique<Cookie>();
381	  cookie->setName(cookieName.first, cookieName.second);
382	  cookie->setValue(cookieValue.first, cookieValue.second);
383	  cookie->setExpiryTime(expiryTime);
384	  cookie->setPersistent(persistent);
385	  cookie->setDomain(std::move(cookieDomain));
386	  cookie->setHostOnly(hostOnly);
387	  cookie->setPath(std::move(cookiePath));
388	  cookie->setSecure(secure);
389	  cookie->setHttpOnly(httpOnly);
390	  cookie->setCreationTime(creationTime);
391	  cookie->setLastAccessTime(creationTime);
392	
393	  return cookie;
394	}
395	
396	bool goodPath(std::string::const_iterator first,
397	              std::string::const_iterator last)
398	{
399	  return first != last && *first == '/';
400	}
401	
402	std::string canonicalizeHost(const std::string& host)
403	{
404	  return util::toLower(host);
405	}
406	
407	bool domainMatch(const std::string& requestHost, const std::string& domain)
408	{
409	  return requestHost == domain ||
410	         (util::endsWith(requestHost, domain) &&
411	          requestHost[requestHost.size() - domain.size() - 1] == '.' &&
412	          !util::isNumericHost(requestHost));
413	}
414	
415	bool pathMatch(const std::string& requestPath, const std::string& path)
416	{
417	  return requestPath == path ||
418	         (util::startsWith(requestPath, path) &&
419	          (path[path.size() - 1] == '/' || requestPath[path.size()] == '/'));
420	}
421	
422	std::string reverseDomainLevel(const std::string& domain)
423	{
424	  std::string r;
425	  if (domain.empty()) {
426	    return r;
427	  }
428	  r.reserve(domain.size());
429	  // Cut trailing dots
430	  std::string::const_iterator s = domain.end() - 1;
431	  for (; *s == '.'; --s) {
432	    if (s == domain.begin()) {
433	      return r;
434	    }
435	  }
436	  std::string::const_iterator t = s + 1;
437	  for (;; --s) {
438	    if (*s == '.') {
439	      r.append(s + 1, t);
440	      r += '.';
441	      t = s;
442	    }
443	    if (s == domain.begin()) {
444	      r.append(s, t);
445	      break;
446	    }
447	  }
448	  return r;
449	}
450	
451	} // namespace cookie
452	
453	} // namespace aria2
