57	std::unique_ptr<Cookie> parseNsCookie(const std::string& cookieStr,
58	                                      time_t creationTime)
59	{
60	  std::vector<Scip> vs;
61	  util::splitIter(cookieStr.begin(), cookieStr.end(), std::back_inserter(vs),
62	                  '\t', true);
63	  if (vs.size() < 6) {
64	    return nullptr;
65	  }
66	  vs[0].first = util::lstripIter(vs[0].first, vs[0].second, '.');
67	  if (vs[5].first == vs[5].second || vs[0].first == vs[0].second ||
68	      !cookie::goodPath(vs[2].first, vs[2].second)) {
69	    return nullptr;
70	  }
71	  int64_t expiryTime;
72	  {
73	    // chrome extension uses subsecond resolution for expiry time.
74	    double expiryTimeDouble;
75	    if (!util::parseDoubleNoThrow(expiryTimeDouble,
76	                                  std::string(vs[4].first, vs[4].second))) {
77	      return nullptr;
78	    }
79	    expiryTime = static_cast<int64_t>(expiryTimeDouble);
80	  }
81	  if (std::numeric_limits<time_t>::max() < expiryTime) {
82	    expiryTime = std::numeric_limits<time_t>::max();
83	  }
84	  else if (std::numeric_limits<time_t>::min() > expiryTime) {
85	    expiryTime = std::numeric_limits<time_t>::min();
86	  }
87	  auto cookie = make_unique<Cookie>();
88	  cookie->setName(vs[5].first, vs[5].second);
89	  if (vs.size() >= 7) {
90	    cookie->setValue(vs[6].first, vs[6].second);
91	  }
92	  else {
93	    cookie->setValue("");
94	  }
95	  cookie->setExpiryTime(expiryTime == 0 ? std::numeric_limits<time_t>::max()
96	                                        : expiryTime);
97	  // aria2 treats expiryTime == 0 means session cookie->
98	  cookie->setPersistent(expiryTime != 0);
99	  cookie->setDomain(vs[0].first, vs[0].second);
100	  cookie->setHostOnly(util::isNumericHost(cookie->getDomain()) ||
101	                      !util::streq(vs[1].first, vs[1].second, "TRUE"));
102	  cookie->setPath(vs[2].first, vs[2].second);
103	  cookie->setSecure(util::streq(vs[3].first, vs[3].second, "TRUE"));
104	  cookie->setCreationTime(creationTime);
105	  return cookie;
106	}
