109	std::vector<std::unique_ptr<Cookie>>
110	NsCookieParser::parse(const std::string& filename, time_t creationTime)
111	{
112	  BufferedFile fp{filename.c_str(), BufferedFile::READ};
113	  if (!fp) {
114	    throw DL_ABORT_EX(fmt("Failed to open file %s", filename.c_str()));
115	  }
116	  std::vector<std::unique_ptr<Cookie>> cookies;
117	  while (1) {
118	    std::string line = fp.getLine();
119	    if (line.empty()) {
120	      if (fp.eof()) {
121	        break;
122	      }
123	      else if (!fp) {
124	        throw DL_ABORT_EX("CookieParser:I/O error.");
125	      }
126	      else {
127	        continue;
128	      }
129	    }
130	    if (line[0] == '#') {
131	      continue;
132	    }
133	    auto c = parseNsCookie(line, creationTime);
134	    if (c) {
135	      cookies.push_back(std::move(c));
136	    }
137	  }
138	  return cookies;
139	}
