59	std::string::const_iterator getNextDigit(std::string::const_iterator first,
60	                                         std::string::const_iterator last)
61	{
62	  for (; first != last && in(static_cast<unsigned char>(*first), 0x30u, 0x39u);
63	       ++first)
64	    ;
65	  return first;
66	}
