70	template <typename InputIterator>
71	int getInteger(InputIterator first, InputIterator last)
72	{
73	  int res = 0;
74	  // We assume *dest won't overflow.
75	  for (; first != last; ++first) {
76	    res *= 10;
77	    res += (*first) - '0';
78	  }
79	  return res;
80	}
