83	bool parseDate(time_t& time, std::string::const_iterator first,
84	               std::string::const_iterator last)
85	{
86	  // Following algorithm is described in
87	  // http://tools.ietf.org/html/rfc6265#section-5.1.1
88	  std::vector<std::string> dateTokens;
89	  for (std::string::const_iterator i = first, eoi = last; i != eoi;) {
90	    unsigned char c = *i;
91	    if (isDelimiter(c)) {
92	      ++i;
93	      continue;
94	    }
95	    std::string::const_iterator s = i;
96	    for (; s != eoi && !isDelimiter(static_cast<unsigned char>(*s)); ++s)
97	      ;
98	    dateTokens.push_back(std::string(i, s));
99	    i = s;
100	  }
101	  int dayOfMonth = 0;
102	  bool foundDayOfMonth = false;
103	  int month = 0;
104	  bool foundMonth = false;
105	  int year = 0;
106	  bool foundYear = false;
107	  int hour = 0;
108	  int minute = 0;
109	  int second = 0;
110	  bool foundTime = false;
111	  for (std::vector<std::string>::const_iterator i = dateTokens.begin(),
112	                                                eoi = dateTokens.end();
113	       i != eoi; ++i) {
114	    if (!foundTime) {
115	      std::string::const_iterator hEnd;
116	      std::string::const_iterator mEnd;
117	      std::string::const_iterator sEnd;
118	      hEnd = getNextDigit((*i).begin(), (*i).end());
119	      size_t len = std::distance((*i).begin(), hEnd);
120	      if (len == 0 || 2 < len || hEnd == (*i).end() || *hEnd != ':') {
121	        goto NOT_TIME;
122	      }
123	      mEnd = getNextDigit(hEnd + 1, (*i).end());
124	      len = std::distance(hEnd + 1, mEnd);
125	      if (len == 0 || 2 < len || mEnd == (*i).end() || *mEnd != ':') {
126	        goto NOT_TIME;
127	      }
128	      sEnd = getNextDigit(mEnd + 1, (*i).end());
129	      len = std::distance(mEnd + 1, sEnd);
130	      if (len == 0 || 2 < len) {
131	        goto NOT_TIME;
132	      }
133	      foundTime = true;
134	      hour = getInteger((*i).begin(), hEnd);
135	      minute = getInteger(hEnd + 1, mEnd);
136	      second = getInteger(mEnd + 1, sEnd);
137	      continue;
138	    NOT_TIME:;
139	    }
140	    if (!foundDayOfMonth) {
141	      std::string::const_iterator j = getNextDigit((*i).begin(), (*i).end());
142	      size_t len = std::distance((*i).begin(), j);
143	      if (1 <= len && len <= 2) {
144	        foundDayOfMonth = true;
145	        dayOfMonth = getInteger((*i).begin(), j);
146	        continue;
147	      }
148	    }
149	    if (!foundMonth) {
150	      static const char MONTH[][12] = {"jan", "feb", "mar", "apr",
151	                                       "may", "jun", "jul", "aug",
152	                                       "sep", "oct", "nov", "dec"};
153	      if ((*i).size() >= 3) {
154	        bool found = false;
155	        size_t j;
156	        for (j = 0; j < 12; ++j) {
157	          if (util::strieq((*i).begin(), (*i).begin() + 3, &MONTH[j][0],
158	                           &MONTH[j][3])) {
159	            found = true;
160	            break;
161	          }
162	        }
163	        if (found) {
164	          foundMonth = true;
165	          month = j + 1;
166	          continue;
167	        }
168	      }
169	    }
170	    if (!foundYear) {
171	      std::string::const_iterator j = getNextDigit((*i).begin(), (*i).end());
172	      size_t len = std::distance((*i).begin(), j);
173	      if (1 <= len && len <= 4) {
174	        foundYear = true;
175	        year = getInteger((*i).begin(), j);
176	        continue;
177	      }
178	    }
179	  }
180	  if (in(year, 70, 99)) {
181	    year += 1900;
182	  }
183	  else if (in(year, 0, 69)) {
184	    year += 2000;
185	  }
186	  if (!foundDayOfMonth || !foundMonth || !foundYear || !foundTime ||
187	      !in(dayOfMonth, 1, 31) || year < 1601 || hour > 23 || minute > 59 ||
188	      second > 59) {
189	    return false;
190	  }
191	  if ((month == 4 || month == 6 || month == 9 || month == 11) &&
192	      dayOfMonth > 30) {
193	    return false;
194	  }
195	  if (month == 2) {
196	    if ((year % 4 == 0 && year % 100 != 0) || year % 400 == 0) {
197	      if (dayOfMonth > 29) {
198	        return false;
199	      }
200	    }
201	    else if (dayOfMonth > 28) {
202	      return false;
203	    }
204	  }
205	
206	  tm timespec;
207	  memset(&timespec, 0, sizeof(timespec));
208	  timespec.tm_sec = second;
209	  timespec.tm_min = minute;
210	  timespec.tm_hour = hour;
211	  timespec.tm_mday = dayOfMonth;
212	  timespec.tm_mon = month - 1;
213	  timespec.tm_year = year - 1900;
214	  time = timegm(&timespec);
215	
216	  return time != -1;
217	}
