219	std::unique_ptr<Cookie> parse(const std::string& cookieStr,
220	                              const std::string& requestHost,
221	                              const std::string& defaultPath,
222	                              time_t creationTime)
223	{
224	  // This implementation is based on the algorithm listed in
225	  // http://tools.ietf.org/html/rfc6265
226	  std::string::const_iterator nvEnd = cookieStr.begin();
227	  std::string::const_iterator end = cookieStr.end();
228	  for (; nvEnd != end && *nvEnd != ';'; ++nvEnd)
229	    ;
230	  std::string::const_iterator eq = cookieStr.begin();
231	  for (; eq != nvEnd && *eq != '='; ++eq)
232	    ;
233	  if (eq == nvEnd) {
234	    return nullptr;
235	  }
236	  std::pair<std::string::const_iterator, std::string::const_iterator> p =
237	      util::stripIter(cookieStr.begin(), eq);
238	  if (p.first == p.second) {
239	    return nullptr;
240	  }
241	  Scip cookieName(p.first, p.second);
242	  p = util::stripIter(eq + 1, nvEnd);
243	  p = util::stripIter(p.first, p.second, "\"");
244	  Scip cookieValue(p.first, p.second);
245	  time_t expiryTime = 0;
246	  bool foundExpires = false;
247	  bool persistent = false;
248	  time_t maxAge = 0;
249	  bool foundMaxAge = false;
250	  std::string cookieDomain;
251	  bool hostOnly = false;
252	  std::string cookiePath;
253	  bool secure = false;
254	  bool httpOnly = false;
255	
256	  if (nvEnd != end) {
257	    ++nvEnd;
258	  }
259	  for (std::string::const_iterator i = nvEnd; i != end;) {
260	    std::string::const_iterator j = std::find(i, end, ';');
261	    std::string::const_iterator eq = std::find(i, j, '=');
262	    p = util::stripIter(i, eq);
263	    std::pair<std::string::const_iterator, std::string::const_iterator> attrp;
264	    if (eq == j) {
265	      attrp.first = attrp.second = j;
266	    }
267	    else {
268	      attrp = util::stripIter(eq + 1, j);
269	    }
270	    i = j;
271	    if (j != end) {
272	      ++i;
273	    }
274	    if (util::strieq(p.first, p.second, "expires")) {
275	      if (parseDate(expiryTime, attrp.first, attrp.second)) {
276	        foundExpires = true;
277	      }
278	      else {
279	        return nullptr;
280	      }
281	    }
282	    else if (util::strieq(p.first, p.second, "max-age")) {
283	      if (attrp.first == attrp.second ||
284	          (!in(static_cast<unsigned char>(*attrp.first), 0x30u, 0x39u) &&
285	           *attrp.first != '-')) {
286	        return nullptr;
287	      }
288	      for (std::string::const_iterator s = attrp.first + 1, eos = attrp.second;
289	           s != eos; ++s) {
290	        if (!in(static_cast<unsigned char>(*s), 0x30u, 0x39u)) {
291	          return nullptr;
292	        }
293	      }
294	      int64_t delta;
295	      if (util::parseLLIntNoThrow(delta,
296	                                  std::string(attrp.first, attrp.second))) {
297	        foundMaxAge = true;
298	        if (delta <= 0) {
299	          maxAge = 0;
300	        }
301	        else {
302	          int64_t n = creationTime;
303	
304	          if (n > std::numeric_limits<int64_t>::max() - delta) {
305	            maxAge = std::numeric_limits<time_t>::max();
306	          }
307	          else {
308	            n += delta;
309	
310	            if (n < 0 || std::numeric_limits<time_t>::max() < n) {
311	              maxAge = std::numeric_limits<time_t>::max();
312	            }
313	            else {
314	              maxAge = n;
315	            }
316	          }
317	        }
318	      }
319	      else {
320	        return nullptr;
321	      }
322	    }
323	    else if (util::strieq(p.first, p.second, "domain")) {
324	      if (attrp.first == attrp.second) {
325	        return nullptr;
326	      }
327	      std::string::const_iterator noDot = attrp.first;
328	      std::string::const_iterator end = attrp.second;
329	      for (; noDot != end && *noDot == '.'; ++noDot)
330	        ;
331	      if (noDot == end) {
332	        return nullptr;
333	      }
334	      cookieDomain.assign(noDot, end);
335	    }
336	    else if (util::strieq(p.first, p.second, "path")) {
337	      if (goodPath(attrp.first, attrp.second)) {
338	        cookiePath.assign(attrp.first, attrp.second);
339	      }
340	      else {
341	        cookiePath = defaultPath;
342	      }
343	    }
344	    else if (util::strieq(p.first, p.second, "secure")) {
345	      secure = true;
346	    }
347	    else if (util::strieq(p.first, p.second, "httponly")) {
348	      httpOnly = true;
349	    }
350	  }
351	
352	  if (foundMaxAge) {
353	    expiryTime = maxAge;
354	    persistent = true;
355	  }
356	  else if (foundExpires) {
357	    persistent = true;
358	  }
